theorem phaseHostTM_q₀ {k : ℕ} {Γ : Type} {I : Type} {Ph : I → Type}
    (M : (i : I) → MultiTapeTM k Γ (Ph i)) (q0 : Σ i, Ph i)
    (red : (i : I) → Ph i → Option (Σ i, Ph i)) : (phaseHostTM M q0 red).q₀ = q0

theorem phaseHostTM_tr_of_red_some {k : ℕ} {Γ : Type} {I : Type} {Ph : I → Type}
    (M : (i : I) → MultiTapeTM k Γ (Ph i)) (q0 : Σ i, Ph i)
    (red : (i : I) → Ph i → Option (Σ i, Ph i)) (i : I) (s : Ph i) {q' : Σ i, Ph i}
    (hs : red i s = some q') (inp : Option Γ) (w : Fin k → Option Γ) :
    (phaseHostTM M q0 red).tr ⟨i, s⟩ inp w = ⟨0, fun _ => (none, 0), none, some q'⟩

theorem StepBlock.forwardLoopCfg_init_workTapes {k n : ℕ} {Q : Type} (entry : Q)
    (M : MultiTapeTM k Bool (Fin (n + 1))) (x : List Bool) (j : Fin (k + 2)) :
    (StepBlock.forwardLoopCfg entry M (M.initCfg x)).workTapes j =
      if j.val = k then FinTM.bufferTape (tableBitsK M.tr)
      else if j.val = k + 1 then fun p => FinTM.bufferTape (unaryFin M.q₀) (p - 2)
      else fun _ => none
